"""Sourcing orchestration. No stock writes, SQL generated by a model, or real transport."""
from datetime import datetime, timezone, timedelta
from decimal import Decimal, ROUND_DOWN
from backend.wo.repository import get_session
from backend.wo.models import Session
from backend.wo.availability import evaluate_availability
from backend.wo.identity import candidate_identity
from . import repository as repo
from .models import VendorResponse
from .simulator import DemoSimulator, VENDORS

def now():return datetime.now(timezone.utc)

def start(body,key):
    # Replay precedes stale-version checks.
    request=body.model_dump()
    previous=repo.query('SELECT id,request FROM pp.demo_run WHERE request_key=%s',(key,))
    if previous:
        if previous[0]['request']!=request:raise repo.ProcurementError('idempotency_conflict','Key already used')
        return get_run(previous[0]['id'], initial=True)
    raw=get_session(body.session_id)
    if not raw:raise repo.ProcurementError('session_not_found','WO not found',404)
    session=Session(**raw)
    if session.company_id!='SYN-COMPANY-01' or session.state!='identified' or session.version!=body.expected_version:
        raise repo.ProcurementError('identity_or_version_conflict','Requires identified synthetic WO at expected version')
    identity=candidate_identity((session.result or {}).get('identified_candidate') or {})
    if not identity:raise repo.ProcurementError('identity_insufficient','Exact brand/base/suffix evidence required')
    availability=evaluate_availability(session).model_dump(mode='json')
    if len(availability['alternatives'])>4:raise repo.ProcurementError('scope_exceeded','MVP supports five warehouse scopes')
    created=now()
    snapshot={'status':'fulfilled_source' if availability['status']=='fulfilled_source' else 'sourcing',
              'identity':identity,'quantity':session.quantity,'destination_warehouse_id':session.warehouse_id,
              'availability':availability,'requested_at':created.isoformat(),'expires_at':(created+timedelta(hours=24)).isoformat(),
              'context':{k:getattr(session,k) for k in ('site_id','production_line_id','station_id','machine_id')},
              'assumption_version':'bearing-mvp-v1','source':'synthetic_demo','simulated':True}
    rid=repo.call('demo_start',session.id,session.version,key,snapshot)
    return get_run(rid, initial=True)

def quote_reasons(quote,snapshot,at):
    if not quote:return ['no_valid_quote']
    reasons=[]
    if quote['identity']!=snapshot['identity']:reasons.append('identity_mismatch')
    if Decimal(quote['qty_available'])<Decimal(snapshot['quantity']):reasons.append('insufficient_stock')
    if quote['quantity_unit']!='Nos' or quote['currency']!='IDR':reasons.append('incomparable_units')
    if quote['destination_warehouse_id']!=snapshot['destination_warehouse_id']:reasons.append('destination_mismatch')
    if datetime.fromisoformat(quote['valid_until'])<=at:reasons.append('expired_quote')
    for k in ('unit_price','tax_amount','shipping_amount','processing_hours','delivered_eta'):
        if quote.get(k) is None:reasons.append('missing_'+k)
    if quote.get('delivered_eta') and quote.get('processing_hours') is not None:
        minimum=datetime.fromisoformat(snapshot['requested_at'])+timedelta(hours=float(Decimal(quote['processing_hours'])))
        if datetime.fromisoformat(quote['delivered_eta'])<minimum:reasons.append('invalid_eta')
    return reasons

def vendor_views(row,events,at):
    result=[]
    if row['snapshot']['status']=='fulfilled_source':return result
    for vendor in VENDORS:
        initial=next((e for e in events if e['vendor_id']==vendor and e['kind']=='rfq'),None)
        counter=next((e for e in events if e['vendor_id']==vendor and e['kind']=='price_counteroffer'),None)
        first=(initial or {}).get('response') or {}
        last=(counter or {}).get('response') or first
        quote=last.get('quote') or first.get('quote')
        reasons=quote_reasons(quote,row['snapshot'],at)
        outcome=last.get('outcome','pending')
        if outcome=='quoted' and 'insufficient_stock' in reasons:outcome='insufficient_stock'
        result.append({'vendor_id':vendor,'outcome':outcome,'quote':quote,'initial_quote':first.get('quote'),
                       'counteroffers_used':int(counter is not None),'eligible':not reasons,'ineligible_reasons':reasons})
    return result

def get_run(rid, initial=False):
    row=repo.run_row(rid);events=[] if initial else repo.exchanges(rid);at=row["created_at"] if initial else now()
    vendors=vendor_views(row,events,at)
    return {'api_version':'procurement-demo-v1','id':rid,'version':1 if initial else row['version'],**row['snapshot'],
            'vendors':vendors,'exchanges':events,'as_of':at.isoformat(),'procurement_executed':False,
            'repair_completed':False,'decision':None if initial else next(iter(repo.query('SELECT * FROM pp.demo_decision WHERE run_id=%s',(rid,))),None)}

def deliver(event,transport):
    if event['response'] is not None:return
    reply=VendorResponse.model_validate(transport.send(event))
    if (reply.event_id,reply.run_id,reply.vendor_id)!=(event['id'],event['run_id'],event['vendor_id']):
        raise repo.ProcurementError('invalid_vendor_response','Correlation mismatch')
    repo.call('demo_receive',event['id'],reply.model_dump(mode='json'))

def advance(rid,transport=None):
    transport=transport or DemoSimulator()
    row=repo.run_row(rid);s=row['snapshot']
    if s['status']=='fulfilled_source' or repo.query('SELECT id FROM pp.demo_decision WHERE run_id=%s',(rid,)):
        return get_run(rid)
    # Bounded to five RFQs and at most five counteroffers. Every send is preceded
    # by a committed outbox event; identical retries reuse event and payload.
    payload={k:s[k] for k in ('identity','quantity','destination_warehouse_id','requested_at','expires_at')}
    payload['currency']='IDR'
    for vendor in VENDORS:
        old=next((e for e in repo.exchanges(rid) if e['vendor_id']==vendor and e['kind']=='rfq'),None)
        event=old or repo.call('demo_enqueue',rid,vendor,'rfq',payload)
        deliver(event,transport)
    # Freeze negotiation basis to initial valid quotes; revisions never trigger
    # another round or change the target of an already reserved counteroffer.
    initial=[e for e in repo.exchanges(rid) if e['kind']=='rfq']
    valid=[]
    for e in initial:
        q=(e['response'] or {}).get('quote')
        if not quote_reasons(q,s,now()):valid.append((e['vendor_id'],q))
    quantity=Decimal(s['quantity'])
    delivered=lambda q:quantity*Decimal(q['unit_price'])+Decimal(q['tax_amount'])+Decimal(q['shipping_amount'])
    benchmark=min((delivered(q) for _,q in valid),default=None)
    for vendor,q in valid:
        previous=next((e for e in repo.exchanges(rid) if e['vendor_id']==vendor and e['kind']=='price_counteroffer'),None)
        if previous:deliver(previous,transport);continue
        if benchmark is None or benchmark>=delivered(q):continue
        target=max(Decimal(0),(benchmark-Decimal(q['tax_amount'])-Decimal(q['shipping_amount']))/quantity).quantize(Decimal('.01'),rounding=ROUND_DOWN)
        event=repo.call('demo_enqueue',rid,vendor,'price_counteroffer',dict(payload,target_unit_price=str(target)))
        deliver(event,transport)
    return get_run(rid)
